import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab}from'../../modeling/parts.js';import{grove,usb}from'./connectors.js';import{spec}from'./dimensions.js';import{addStickers}from'./stickers.js';import data from'./geometry-data.js';const tau=Math.PI*2;
function solid(parent,s,d,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:48}),m,p,n);}
function ring(parent,outer,inner,d,p,m,n){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);const h=new THREE.Path();h.absarc(0,0,inner,0,tau,false);s.holes.push(h);return solid(parent,s,d,p,m,n);}
function board(host){const s=new THREE.Shape(),x=10,r=3.8,row=-4,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2);s.moveTo(-5,-14.5);s.lineTo(-8,-14.5);s.lineTo(-x,-12.5);s.lineTo(-x,row-dy);s.absarc(-8,row,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,12.5);s.lineTo(-8,14.5);s.lineTo(8,14.5);s.lineTo(x,12.5);s.lineTo(x,row+dy);s.absarc(8,row,r,a,tau-a,false);s.lineTo(x,-12.5);s.lineTo(8,-14.5);s.lineTo(5,-14.5);s.lineTo(5,-9.2);s.lineTo(-5,-9.2);s.closePath();const pinHoles=[];for(const x of[-7.5,0,7.5])for(const y of[8.5,6.5,4.5,2.5])pinHoles.push([x+.5,y]);for(const[x,y,r]of[[0,-4,1.8],...pinHoles.map(([x,y])=>[x,y,.4])]){const h=new THREE.Path();h.absarc(x,y,r,0,tau,false);s.holes.push(h);}const green=materials.plastic(0x285e40,{roughness:.9}),metal=materials.metal(0xafb7a9,{roughness:.5}),pcb=solid(host.body,s,.8,[0,0,.8],green,'TypeC to Grove passive carrier PCB with true retaining and12 solder through-bores'),solderPads=[],barrels=[];for(const[x,y]of pinHoles){solderPads.push(ring(host.body,.7,.28,.06,[x,y,1.6],metal,'TypeC to Grove actual annular Grove solder land'));barrels.push(ring(host.body,.4,.28,.8,[x,y,.8],metal,'TypeC to Grove Grove solder through-hole barrel'));}const resistors=[];for(const x of[-7.1,7.1]){const q=slab(host.body,1.3,.75,.5,.04,[x,-10.5,1.6],materials.plastic(0x242923,{roughness:.85}),[],.005);q.name='TypeC to Grove actual fixed5.1K CC pull-down resistor envelope';resistors.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.2,.75,.12),metal,[x+sign*.53,-10.5,1.66],'TypeC to Grove fixed resistor solder terminal');}return{pcb,pinHoles,solderPads,barrels,resistors};}
function films(host){const labels={},film=materials.plastic(0xe2e4de,{roughness:.87});for(const face of['power','back']){const p=slab(host.body,...spec.labels[face].size,.08,.08,spec.labels[face].position,film,[],.005);p.name='TypeC to Grove real '+face+' adhesive film';p.userData={role:'physical-label-substrate',face};labels[face]=p;}const w=21.4,h=5,r=2.6,s=new THREE.Shape();s.moveTo(-w/2,-h/2);s.lineTo(w/2,-h/2);s.lineTo(w/2,h/2-r);s.quadraticCurveTo(w/2,h/2,w/2-r,h/2);s.lineTo(-w/2+r,h/2);s.quadraticCurveTo(-w/2,h/2,-w/2,h/2-r);s.closePath();labels.banner=solid(host.body,s,.08,spec.labels.banner.position,film,'TypeC to Grove real rounded-top banner adhesive film');labels.banner.userData={role:'physical-label-substrate',face:'banner'};return labels;}
export function buildTypecToGrove(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e2,{roughness:.8})}),pcb=board(host),input=grove(host,0),outputs=[grove(host,1),grove(host,2)],power=usb(host),metal=materials.metal(0xaeb6a9,{roughness:.43}),headShape=new THREE.Shape();headShape.absarc(0,0,1.6,0,tau,false);const hole=new THREE.Path();for(let i=0;i<6;i++){const x=.65*Math.cos(i*tau/6),y=.65*Math.sin(i*tau/6);if(i)hole.lineTo(x,y);else hole.moveTo(x,y);}hole.closePath();headShape.holes.push(hole);const head=solid(host.body,headShape,.45,[0,-4,-3.95],metal,'TypeC to Grove actual annular metal retaining head with true hex socket'),blind=mesh(host.body,new THREE.CylinderGeometry(.65,.65,.12,6).rotateX(Math.PI/2),materials.metal(0x596056),[0,-4,-3.44],'TypeC to Grove real retaining hex-socket blind floor'),shank=mesh(host.body,new THREE.CylinderGeometry(.6,.6,4.7,24).rotateX(Math.PI/2),metal,[0,-4,-.75],'TypeC to Grove concealed fixed retaining screw shank'),labels=films(host);host.typecToGroveAssembly={parts,pcb,input,outputs,usb:power,fixing:{head,blind,shank},labels};host.unitStickers=addStickers(host);}
